"""Django system checks for the inbound-email pipeline.

Refuses to start non-DEBUG environments that still hold the
``local-dev-*`` placeholder secrets baked into ``docker-compose.local.yml``.
This prevents accidental promotion of dev defaults into staging or prod
where the MTA endpoint is internet-reachable.
"""

from __future__ import annotations

from typing import Any

from django.conf import settings
from django.core.checks import Error, Tags, register

_DEV_DEFAULTS = {
    "MTA_INGEST_SECRET": "local-dev-mta-ingest-secret",
    "MTA_HMAC_KEY": "local-dev-mta-hmac-key",
    "MTA_INTERNAL_TOKEN": "local-dev-mta-internal-token",
}

# Secrets below this length are insufficient even outside the dev-default set.
_MIN_SECRET_LENGTH = 32


@register(Tags.security)  # type: ignore[misc]
def inbound_email_secret_strength(app_configs: Any, **_: Any) -> list[Error]:
    """Block startup when MTA secrets are still set to dev placeholders."""

    if settings.DEBUG:
        return []

    issues: list[Error] = []
    for name, dev_value in _DEV_DEFAULTS.items():
        value = getattr(settings, name, "")
        if not value:
            issues.append(
                Error(
                    f"{name} is not configured; the MTA ingress endpoint will be unauthenticated.",
                    id=f"inbound_email.E001.{name.lower()}",
                )
            )
            continue
        if value == dev_value:
            issues.append(
                Error(
                    f"{name} is set to the docker-compose dev default value. "
                    "Rotate to a unique secret before deploying.",
                    id=f"inbound_email.E002.{name.lower()}",
                )
            )
        elif len(value) < _MIN_SECRET_LENGTH:
            issues.append(
                Error(
                    f"{name} is shorter than {_MIN_SECRET_LENGTH} characters.",
                    id=f"inbound_email.E003.{name.lower()}",
                )
            )
    return issues

