        """
        Get media for a specific family, optionally including meta family media.

        Args:
            family: FamilyGroup instance
            include_meta: Whether to include media from meta family members

        Returns:
            QuerySet of media filtered by family permissions
        """
        if include_meta:
            all_family_ids = _collect_meta_family_member_ids([family.id])
            if all_family_ids:
                return self.get_queryset().filter(
                    event__family_group_id__in=all_family_ids
                )

