def normalize_capture_payload(
    *, capture_type: str, raw_text: str = "", raw_payload: dict[str, Any] | None = None
) -> dict[str, Any]:
    payload = dict(raw_payload or {})
    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
    if "suggested_items" not in payload and lines:
        payload["suggested_items"] = lines
    payload.setdefault("suggested_title", lines[0] if lines else "Inbox item")
    payload.setdefault(
        "suggested_kind",
        "grocery_list" if capture_type == InboxCapture.CaptureType.PHOTO else "task",
    )
    if "preview_text" not in payload:
        if lines:
            payload["preview_text"] = " | ".join(lines[:2])[:140]
        elif capture_type == InboxCapture.CaptureType.PHOTO:
            payload["preview_text"] = "Photo capture ready for review"
        elif capture_type == InboxCapture.CaptureType.EMAIL:
            payload["preview_text"] = "Email capture ready for review"
    return payload


def normalize_desktop_capture_payload(
    *,
    capture_type: str,
    raw_text: str = "",
    raw_payload: dict[str, Any] | None = None,
    source_kind: str = "",
    source_url: str = "",
    source_domain: str = "",
    preview_title: str = "",
    preview_text: str = "",
    preview_price_text: str = "",
    thumbnail_ref: str = "",
    captured_from: str = "",
) -> dict[str, Any]:
    payload = normalize_capture_payload(
        capture_type=capture_type,
        raw_text=raw_text,
        raw_payload=raw_payload,
    )

    if any(
        [
            source_url.strip(),
            source_domain.strip(),
            preview_price_text.strip(),
            thumbnail_ref.strip(),
        ]
    ):
        payload["suggested_kind"] = "grocery_list"

    stable_fields = {
        "source_kind": source_kind.strip(),
        "source_url": source_url.strip(),
        "source_domain": source_domain.strip(),
        "preview_title": preview_title.strip(),
        "preview_text": preview_text.strip()
        or str(payload.get("preview_text") or "").strip(),
        "preview_price_text": preview_price_text.strip(),
        "thumbnail_ref": thumbnail_ref.strip(),
        "captured_from": captured_from.strip(),
    }
    for key, value in stable_fields.items():
        if value:
            payload[key] = value
        else:
            payload.setdefault(key, "")

    if (
        payload["preview_title"]
        and not str(payload.get("suggested_title") or "").strip()
    ):
        payload["suggested_title"] = payload["preview_title"]

    return payload


