@transaction.atomic
def convert_capture_to_task(
    capture: InboxCapture,
    *,
    title: str | None = None,
    notes: str = "",
    assigned_to: User | None = None,
) -> FamilyTask:
    task = create_task_from_household_action(
        family=capture.family,
        title=title or capture.raw_text or "Inbox item",
        notes=notes or capture.raw_text,
        source_client_app=capture.source_client_app or ClientApp.ORGANIZE,
        created_by=capture.created_by,
        assigned_to=assigned_to,
        source_object=capture,
    )
    capture.converted_task = task
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(update_fields=["converted_task", "status", "updated_at"])
    return task


@transaction.atomic
def convert_capture_to_grocery_list(
    capture: InboxCapture,
    *,
    name: str | None = None,
    description: str = "",
    owner: User | None = None,
) -> GroceryList:
    owner = owner or capture.created_by
    if owner is None:
        raise ValueError("Inbox capture cannot be converted without an owning user.")

    grocery_list = GroceryList.objects.create(
        family=capture.family,
        name=name
        or capture.normalized_payload.get("suggested_title")
        or "Shopping list",
        description=description or capture.raw_text or "",
        owner=owner,
        is_group=True,
    )

    items = [
        GroceryItem(
            grocery_list=grocery_list,
            name=item_name,
            position=position,
            created_by=owner,
        )
        for position, item_name in enumerate(
            capture.normalized_payload.get("suggested_items", []), start=1
        )
    ]
    if items:
        GroceryItem.objects.bulk_create(items)

    capture.converted_grocery_list = grocery_list
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(update_fields=["converted_grocery_list", "status", "updated_at"])
    return grocery_list


@transaction.atomic
def convert_capture_to_event(
    capture: InboxCapture,
    event_payload: dict[str, Any],
    *,
    source_client_app: str = ClientApp.ORGANIZE,
) -> Event:
    """Materialize an Event from an InboxCapture proposal.

    Used for clean .ics auto-conversion and for user-confirmed event
    proposals from the review queue. Sets ``external_source='inbox_email'``
    plus the ICS UID as ``external_id`` so future updates to the same UID
    can ``update_or_create`` against this row instead of duplicating.
    """

    title = (event_payload.get("summary") or event_payload.get("title") or "").strip()
    if not title:
        raise ValueError("Event conversion requires a title or summary.")

    starts_at_raw = event_payload.get("starts_at") or event_payload.get("start_time")
    ends_at_raw = event_payload.get("ends_at") or event_payload.get("end_time")
    if not starts_at_raw:
        raise ValueError("Event conversion requires starts_at / start_time.")

    def _parse_dt(value: Any) -> dt_datetime:
        if isinstance(value, dt_datetime):
            dt_value = value
        else:
            dt_value = dt_datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if timezone.is_naive(dt_value):
            dt_value = timezone.make_aware(dt_value, dt_timezone.utc)
        return dt_value

    start_time = _parse_dt(starts_at_raw)
    end_time = (
        _parse_dt(ends_at_raw) if ends_at_raw else start_time + timedelta(hours=1)
    )

    creator = capture.created_by
    if creator is None:
        membership = (
            FamilyMembership.objects.filter(family=capture.family, is_active=True)
            .order_by("-is_admin", "joined_at")
            .first()
        )
        if membership is None:
            raise ValueError(
                "Cannot convert capture to event: no active member on family."
            )
        creator = membership.user

    uid = (event_payload.get("uid") or "").strip()
    # Namespace external_id by family so an ICS UID from one family cannot
    # match (and overwrite) another family's existing inbox_email event.
    namespaced_uid = uid or f"capture:{capture.pk}"
    external_id = f"{capture.family.pk}:{namespaced_uid}"

    # No DB-level unique constraint on (external_source, external_id) in the
    # Event table today, so we filter-then-write under the surrounding
    # @transaction.atomic, scoped to the family, to avoid MultipleObjectsReturned
    # and to prevent cross-tenant lookups.
    event = (
        Event.secure.for_family(capture.family, include_meta=False)
        .select_for_update()
        .filter(
            external_source="inbox_email",
            external_id=external_id,
        )
        .first()
    )
    created = event is None
    event_fields = {
        "title": title,
        "description": (event_payload.get("description") or "")[:5000],
        "location": (event_payload.get("location") or "")[:255],
        "start_time": start_time,
        "end_time": end_time,
        "family_group": capture.family,
        "creator": creator,
        "is_external": True,
        "external_source": "inbox_email",
        "external_id": external_id,
    }
    if event is None:
        event = cast(Event, Event.secure.create(**event_fields))
    else:
        for field, value in event_fields.items():
            setattr(event, field, value)
        event.save()

    capture.converted_event = event
    capture.status = InboxCapture.Status.CONVERTED
    capture.source_client_app = canonicalize_client_app(
        capture.source_client_app, default=""
    ) or canonicalize_client_app(source_client_app, default=ClientApp.ORGANIZE)
    capture.save(
        update_fields=[
            "converted_event",
            "status",
            "source_client_app",
            "updated_at",
        ]
    )
    logger.info(
        "organize.convert_capture_to_event",
        extra={
            "capture": str(capture.pk),
            "event": str(event.pk),
            "created_new_event": created,
            "uid": uid,
        },
    )
    return event


@transaction.atomic
def create_tasks_from_capture(
    capture: InboxCapture,
    *,
    reviewed_tasks: list[dict[str, Any]],
) -> list[FamilyTask]:
    capture = InboxCapture.objects.select_for_update().get(pk=capture.pk)
    normalized_payload = dict(capture.normalized_payload or {})
    existing_task_ids = [
        str(task_id)
        for task_id in normalized_payload.get("created_task_ids", [])
        if isinstance(task_id, str)
    ]
    if capture.status == InboxCapture.Status.CONVERTED:
        existing_task_map = {
            str(task.id): task
            for task in FamilyTask.objects.filter(id__in=existing_task_ids)
        }
        existing_tasks = [
            existing_task_map[task_id]
            for task_id in existing_task_ids
            if task_id in existing_task_map
        ]
        if not existing_tasks and capture.converted_task_id:
            existing_tasks = [capture.converted_task] if capture.converted_task else []
        if existing_tasks:
            return existing_tasks
        raise TaskCaptureCreateError(
            "Tasks have already been created from this capture."
        )

    selected_tasks = [
        task
        for task in reviewed_tasks
        if task.get("selected", True) and str(task.get("title", "")).strip()
    ]
    if not selected_tasks:
        raise TaskCaptureCreateError("Select at least one task to create.")

    created_tasks: list[FamilyTask] = []
    for task_data in selected_tasks:
        created_tasks.append(
            create_task_from_household_action(
                family=capture.family,
                title=str(task_data["title"]).strip(),
                notes=str(task_data.get("notes") or "").strip(),
                source_client_app=capture.source_client_app or ClientApp.ORGANIZE,
                created_by=capture.created_by,
                source_object=capture,
            )
        )

    normalized_payload["reviewed_tasks"] = selected_tasks
    normalized_payload["created_task_ids"] = [str(task.id) for task in created_tasks]
    capture.converted_task = created_tasks[0]
    capture.normalized_payload = normalized_payload
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(
        update_fields=[
            "converted_task",
            "normalized_payload",
            "status",
            "updated_at",
        ]
    )
    return created_tasks


def dismiss_capture(capture: InboxCapture) -> InboxCapture:
    capture.status = InboxCapture.Status.DISMISSED
    capture.save(update_fields=["status", "updated_at"])
    return capture


def get_dashboard_payload(
    user: User, request: Any = None, family_id: str | None = None
) -> dict[str, Any]:
    started_at = perf_counter()
    now = timezone.now()
    local_now = timezone.localtime(now)
    today_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
    today_events_end = local_now.replace(
        hour=23, minute=59, second=59, microsecond=999999
    )
    family_ids = get_accessible_family_ids(user)
    tasks = (
        FamilyTask.objects.filter(family_id__in=family_ids)
        .select_related("family", "assigned_to", "created_by", "linked_event")
        .order_by("due_at", "created_at")
    )
    today_bucket_end = now + timedelta(days=1)
    week_end = now + timedelta(days=7)
    upcoming_events = (
        Event.secure.for_user(user, include_meta=False)
        .filter(end_time__gte=now)
        .order_by("start_time")
        .only("id", "title", "start_time", "end_time", "family_group_id")
    )[:6]
    if family_id and family_id not in {str(fid) for fid in family_ids}:
        family_id = None
    today_events_qs = Event.secure.for_user(user, include_meta=False).filter(
        end_time__gte=today_start, start_time__lte=today_events_end
    )
    if family_id:
        today_events_qs = today_events_qs.filter(family_group_id=family_id)
    today_events = today_events_qs.order_by("start_time")
    dashboard_lists = list(
        GroceryList.objects.filter(family_id__in=family_ids)
        .only("id", "name", "updated_at", "list_type")
        .annotate(dashboard_item_count=Count("items", distinct=True))
        .order_by("-updated_at")
    )
    inbox_captures = (
        InboxCapture.objects.filter(
            family_id__in=family_ids,
            status__in=[
                InboxCapture.Status.CAPTURED,
                InboxCapture.Status.PROCESSING,
                InboxCapture.Status.NEEDS_REVIEW,
            ],
        )
        .select_related("created_by", "converted_task", "converted_grocery_list")
        .order_by("-created_at")
    )[:5]
    payload = {
        "today": tasks.filter(
            status=FamilyTask.Status.PENDING,
            due_at__isnull=False,
            due_at__gte=now,
            due_at__lte=today_bucket_end,
        ),
        "this_week": tasks.filter(
            status=FamilyTask.Status.PENDING,
            due_at__isnull=False,
            due_at__gt=today_bucket_end,
            due_at__lte=week_end,
        ),
        "overdue": tasks.filter(
            status=FamilyTask.Status.PENDING,
            due_at__lt=now,
        ),
        "today_events": today_events,
        "upcoming_events": upcoming_events,
        "grocery_lists": dashboard_lists,
        "lists": dashboard_lists,
        "inbox": inbox_captures,
        "client_app_context": get_client_app_context(request),
    }
    logger.info(
        "Organize dashboard payload built in %.2fms",
        (perf_counter() - started_at) * 1000,
        extra={
            "client_app": getattr(request, "client_app", None),
            "family_count": len(family_ids),
        },
    )
    return payload


@transaction.atomic
def materialize_chore_program(
    program: ChoreProgram, *, start: Any = None
) -> list[FamilyTask]:
    # Re-fetch with row lock to prevent concurrent materialization races
    program = ChoreProgram.objects.select_for_update().get(pk=program.pk)

    if not program.is_active:
        return []

    start = start or timezone.now()
    period_map = {
        ChoreProgram.Frequency.DAILY: 1,
        ChoreProgram.Frequency.WEEKLY: 7,
        ChoreProgram.Frequency.BIWEEKLY: 14,
        ChoreProgram.Frequency.MONTHLY: 30,
    }
    period_days = period_map[ChoreProgram.Frequency(program.frequency)]
    period = timedelta(days=period_days)

    # Compute stable window boundaries so repeat calls are idempotent.
    # Anchor to rotation_anchor_date if available, otherwise use today.
    anchor = program.rotation_anchor_date or timezone.localdate(start)
    today = timezone.localdate(start)
    # Find the start of the current window relative to the anchor
    days_since_anchor = (today - anchor).days
    current_window_offset = (days_since_anchor // period_days) * period_days
    window_start = anchor + timedelta(days=current_window_offset)

    window_boundaries = [window_start, window_start + period]
    tasks: list[FamilyTask] = []
    rotation_increments = 0

    for win_start in window_boundaries:
        win_end = win_start + timedelta(days=period_days - 1)
        # Use window midpoint as a stable due_at for idempotent get_or_create
        due_at = timezone.make_aware(
            dt_datetime.combine(win_start, dt_datetime.min.time())
        ) + timedelta(days=period_days // 2)

        assigned_to = program.assigned_to
        if (
            program.assignment_mode == ChoreProgram.AssignmentMode.ROUND_ROBIN
            and program.rotation_member_ids
        ):
            member_ids = list(program.rotation_member_ids)
            idx = (program.current_rotation_index + rotation_increments) % len(
                member_ids
            )
            assignee_id = member_ids[idx]
            assigned_to = User.objects.filter(id=assignee_id).first()

        task, created = FamilyTask.objects.get_or_create(
            family=program.family,
            title=program.title,
            task_kind=FamilyTask.TaskKind.CHORE,
            chore_program=program,
            window_starts_on=win_start,
            defaults={
                "notes": program.notes,
                "due_at": due_at,
                "window_ends_on": win_end,
                "created_by": program.created_by,
                "assigned_to": assigned_to,
                "source_client_app": ClientApp.ORGANIZE,
            },
        )
        if created:
            tasks.append(task)
            if (
                program.assignment_mode == ChoreProgram.AssignmentMode.ROUND_ROBIN
                and program.rotation_member_ids
            ):
                rotation_increments += 1

    if tasks:
        if rotation_increments:
            ChoreProgram.objects.filter(pk=program.pk).update(
                current_rotation_index=F("current_rotation_index")
                + rotation_increments,
            )
        ChoreProgram.objects.filter(pk=program.pk).update(
            last_materialized_for=timezone.localdate(tasks[-1].due_at or start),
        )
    return tasks


def _add_months(base: dt_datetime, months: int) -> dt_datetime:
    """Return base shifted by `months`, clamping to the last day of the target month."""
    month_index = base.month - 1 + months
    year = base.year + month_index // 12
    month = month_index % 12 + 1
    # Clamp the day to the last day of the target month (handles Jan 31 -> Feb 28/29).
    if month == 12:
        next_month_first = base.replace(year=year + 1, month=1, day=1)
    else:
        next_month_first = base.replace(year=year, month=month + 1, day=1)
    last_day_of_target = (next_month_first - timedelta(days=1)).day
    day = min(base.day, last_day_of_target)
    return base.replace(year=year, month=month, day=day)


def compute_next_due_at(
    current_due_at: dt_datetime | None,
    recurrence: str,
) -> dt_datetime | None:
    """Return the next `due_at` for a recurring task, or None if recurrence is NONE.

    If no current due_at is set, anchors on `timezone.now()` so the next occurrence
    still has a sensible timestamp. Time-of-day is preserved across increments.
    """
    if recurrence == FamilyTask.Recurrence.NONE:
        return None
    anchor = current_due_at or timezone.now()
    if recurrence == FamilyTask.Recurrence.DAILY:
        return anchor + timedelta(days=1)
    if recurrence == FamilyTask.Recurrence.WEEKDAYS:
        # Advance by one day; if the result lands on Sat (5) or Sun (6), skip to Mon.
        candidate = anchor + timedelta(days=1)
        weekday = candidate.weekday()
        if weekday == 5:  # Saturday
            candidate += timedelta(days=2)
        elif weekday == 6:  # Sunday
            candidate += timedelta(days=1)
        return candidate
    if recurrence == FamilyTask.Recurrence.WEEKLY:
        return anchor + timedelta(days=7)
    if recurrence == FamilyTask.Recurrence.MONTHLY:
        return _add_months(anchor, 1)
    # Unknown recurrence value — treat as none rather than crashing.
    logger.warning("compute_next_due_at received unknown recurrence: %r", recurrence)
    return None


def spawn_next_occurrence(task: FamilyTask) -> FamilyTask | None:
    """Create and return the next occurrence of a recurring task, or None.

    The new occurrence inherits title, notes, assignment, and recurrence settings
    from the source task. Its `recurrence_parent` points at the series' root
    (the original task, or the parent of a spawned occurrence).
    """
    if task.recurrence == FamilyTask.Recurrence.NONE:
        return None
    next_due = compute_next_due_at(task.due_at, task.recurrence)
    parent = task.recurrence_parent or task
    return FamilyTask.objects.create(
        family=task.family,
        title=task.title,
        notes=task.notes,
        status=FamilyTask.Status.PENDING,
        due_at=next_due,
        assigned_to=task.assigned_to,
        created_by=task.created_by,
        source_client_app=task.source_client_app,
        task_kind=task.task_kind,
        recurrence=task.recurrence,
        recurrence_parent=parent,
    )
